#!/usr/bin/env python3
"""Safely apply verified V130->V131 patch; abort on unexpected source."""
import base64
import subprocess
import zlib
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
OLD_SHA="68deeacff0cf594d3a1d000f219883d10caf7935"
NEW_SHA="625a24ab770300271351e25e25b5ee72a71b909c"
PATCH_ZLIB_B64=""

def sha():
    return subprocess.check_output(["git","hash-object","app.py"],cwd=ROOT,text=True).strip()

def main():
    found=sha()
    if found==NEW_SHA:
        print("V131 app.py already installed")
        return
    if found!=OLD_SHA:
        raise SystemExit("Aborting: app.py is not expected V130 baseline: "+found)
    patch=zlib.decompress(base64.b64decode(PATCH_ZLIB_B64)).decode("utf-8")
    for check in [True,False]:
        command=["git","apply","--unidiff-zero"]
        if check: command.append("--check")
        subprocess.run(command,cwd=ROOT,input=patch,text=True,check=True)
    if sha()!=NEW_SHA:
        raise SystemExit("Aborting: V131 output hash mismatch")
    subprocess.run(["python","-m","py_compile","app.py"],cwd=ROOT,check=True)
    print("V131 generated; exact tested blob SHA verified")

if __name__=="__main__":
    main()
